package com.xpcounterhider;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(XpCounterHiderConfig.GROUP)
public interface XpCounterHiderConfig extends Config
{
	String GROUP = "xpcounterhider";

	enum MaxDefinition
	{
		SKILL_LEVEL("Skill level"),
		TOTAL_XP("Total XP");

		private final String name;

		MaxDefinition(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	@ConfigItem(
		keyName = "maxDefinition",
		name = "\"Maxed\" means",
		description = "How to decide a skill is maxed.<br>"
			+ "Skill level: hide at or above the configured level.<br>"
			+ "Total XP: hide at or above the configured XP.",
		position = 0
	)
	default MaxDefinition maxDefinition()
	{
		return MaxDefinition.SKILL_LEVEL;
	}

	@ConfigItem(
		keyName = "hideAtLevel",
		name = "Hide at level",
		description = "Hide the counter when the tracked skill is at or above this level. "
			+ "Virtual levels 100-126 are supported. Only used when \"Maxed\" means is set to Skill level.",
		position = 1
	)
	@Range(min = 2, max = 126)
	default int hideAtLevel()
	{
		return 99;
	}

	@ConfigItem(
		keyName = "hideAtXp",
		name = "Hide at XP",
		description = "Hide the counter when the tracked skill is at or above this much XP. "
			+ "Only used when \"Maxed\" means is set to Total XP.",
		position = 2
	)
	@Range(min = 1, max = 200_000_000)
	default int hideAtXp()
	{
		return 200_000_000;
	}
}

package com.xpcounterhider;

import com.google.inject.Provides;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "XP Counter Hider",
	description = "Hides the in-game XP counter and progress bar when the tracked skill is already maxed",
	tags = {"experience", "xp", "counter", "progress", "bar", "max", "maxed", "skill", "hide"}
)
public class XpCounterHiderPlugin extends Plugin
{
	/**
	 * The skill-icon sprite the in-game XP counter draws, mapped to its skill.
	 * The counter shows exactly one of these at a time (or a non-skill icon such
	 * as "Total", which is intentionally absent so it is never hidden).
	 */
	private static final Map<Integer, Skill> SKILL_BY_SPRITE = new HashMap<>();

	static
	{
		SKILL_BY_SPRITE.put(SpriteID.Staticons.ATTACK, Skill.ATTACK);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.STRENGTH, Skill.STRENGTH);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.DEFENCE, Skill.DEFENCE);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.RANGED, Skill.RANGED);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.PRAYER, Skill.PRAYER);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.MAGIC, Skill.MAGIC);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.HITPOINTS, Skill.HITPOINTS);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.AGILITY, Skill.AGILITY);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.HERBLORE, Skill.HERBLORE);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.THIEVING, Skill.THIEVING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.CRAFTING, Skill.CRAFTING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.FLETCHING, Skill.FLETCHING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.MINING, Skill.MINING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.SMITHING, Skill.SMITHING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.FISHING, Skill.FISHING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.COOKING, Skill.COOKING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.FIREMAKING, Skill.FIREMAKING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons.WOODCUTTING, Skill.WOODCUTTING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons2.RUNECRAFT, Skill.RUNECRAFT);
		SKILL_BY_SPRITE.put(SpriteID.Staticons2.SLAYER, Skill.SLAYER);
		SKILL_BY_SPRITE.put(SpriteID.Staticons2.FARMING, Skill.FARMING);
		SKILL_BY_SPRITE.put(SpriteID.Staticons2.HUNTER, Skill.HUNTER);
		SKILL_BY_SPRITE.put(SpriteID.Staticons2.CONSTRUCTION, Skill.CONSTRUCTION);
		SKILL_BY_SPRITE.put(SpriteID.Staticons2.SAILING, Skill.SAILING);
	}

	@Inject
	private Client client;

	@Inject
	private XpCounterHiderConfig config;

	// Tracks whether we are the ones currently hiding the box, so that we only
	// ever un-hide what we hid and never fight the game's own visibility.
	private boolean hiddenByUs;

	@Provides
	XpCounterHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(XpCounterHiderConfig.class);
	}

	@Override
	protected void shutDown()
	{
		if (hiddenByUs)
		{
			setBoxHidden(false);
			hiddenByUs = false;
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender beforeRender)
	{
		final Skill skill = getDisplayedSkill();
		final boolean shouldHide = skill != null && isMaxed(skill);

		if (shouldHide)
		{
			setBoxHidden(true);
			hiddenByUs = true;
		}
		else if (hiddenByUs)
		{
			setBoxHidden(false);
			hiddenByUs = false;
		}
	}

	/**
	 * @return the skill the XP counter is currently displaying, or null if the
	 * counter is not shown or is showing something other than a single skill.
	 */
	private Skill getDisplayedSkill()
	{
		final Widget icon = client.getWidget(InterfaceID.XpDrops.COUNTER_ICON);
		if (icon == null)
		{
			return null;
		}
		return SKILL_BY_SPRITE.get(icon.getSpriteId());
	}

	private boolean isMaxed(Skill skill)
	{
		final int xp = client.getSkillExperience(skill);
		switch (config.maxDefinition())
		{
			case TOTAL_XP:
				return xp >= config.hideAtXp();
			case SKILL_LEVEL:
			default:
				return Experience.getLevelForXp(xp) >= config.hideAtLevel();
		}
	}

	private void setBoxHidden(boolean hidden)
	{
		final Widget counter = client.getWidget(InterfaceID.XpDrops.COUNTER_CONTAINER);
		if (counter != null)
		{
			counter.setHidden(hidden);
		}
		final Widget progress = client.getWidget(InterfaceID.XpDrops.PROGRESS_CONTAINER);
		if (progress != null)
		{
			progress.setHidden(hidden);
		}
	}
}
